<script setup lang="ts">
import type{AccountSummary}from'@/types/security';
defineProps<{rows:AccountSummary[];currentAccountId?:string}>();
const emit=defineEmits<{toggle:[account:AccountSummary];reset:[account:AccountSummary];unlock:[account:AccountSummary];permissions:[account:AccountSummary];audit:[account:AccountSummary]}>();
const labels:Record<string,string>={ENABLED:'正常',DISABLED:'已停用',LOCKED:'已锁定',PASSWORD_CHANGE_REQUIRED:'待修改密码'};
function command(action:string,account:AccountSummary){if(action==='audit')emit('audit',account);else if(action==='unlock')emit('unlock',account);else if(action==='reset')emit('reset',account);else if(action==='toggle')emit('toggle',account);}
</script>
<template><el-table :data="rows"><el-table-column label="用户" min-width="170"><template #default="{row}"><div class="primary-cell"><b>{{row.displayName}}</b><span class="mono">{{row.username}}</span></div></template></el-table-column><el-table-column label="角色" width="110"><template #default="{row}"><el-tag effect="plain">{{row.role==='SUPER_ADMIN'?'管理员':'普通用户'}}</el-tag></template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag effect="plain" :type="row.status==='ENABLED'?'success':'warning'">{{labels[row.status]}}</el-tag></template></el-table-column><el-table-column prop="repositoryPermissionCount" label="仓库权限" width="100"/><el-table-column label="最近登录" min-width="165"><template #default="{row}">{{row.lastLoginAt?new Date(row.lastLoginAt).toLocaleString():'—'}}</template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button v-if="row.role==='NORMAL'" link type="primary" @click="emit('permissions',row)">仓库权限</el-button><el-dropdown trigger="click" @command="command($event,row)"><el-button link type="primary">更多操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="audit">查看审计</el-dropdown-item><el-dropdown-item v-if="row.status==='LOCKED'" command="unlock" divided>解锁账号</el-dropdown-item><el-dropdown-item command="reset" :divided="row.status!=='LOCKED'">重置密码</el-dropdown-item><el-dropdown-item command="toggle" :disabled="row.id===currentAccountId" divided>{{row.status==='DISABLED'?'启用账号':'停用账号'}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table></template>
